#!/bin/bash
# macOS per-user installer for the Character API helper (native messaging host for Chrome and Brave).
#   bash setup.sh install     register this folder's CharacterBridge (Install.command)
#   bash setup.sh uninstall   remove registrations that point at this folder (Uninstall.command)
# Writes only <browser>/NativeMessagingHosts/com.tabletopvr.character_bridge.json for Chrome and Brave, and only
# when that file is absent or was generated by this installer. Never touches browser profiles, needs no admin
# rights, and changes nothing if any browser's check fails. Bash 3.2 (the macOS /bin/bash).
set -u
umask 022

HOST='com.tabletopvr.character_bridge'
ORIGIN='chrome-extension://abeakpcagojpphodembeeajfjgmcadnc/'
DESCRIPTION='Tabletop VR Character Bridge'
# CHARACTER_API_INSTALL_TEST=1 is for the automated tests only (they run on Linux with a temporary HOME):
# it skips the macOS-only steps (platform check, quarantine, code signature).
TEST="${CHARACTER_API_INSTALL_TEST:-}"

fail() { printf 'Installation stopped: %s\nNo browser registration was changed.\n' "$1" >&2; exit 1; }
say() { printf '%s\n' "$1"; }

action="${1:-install}"
case "$action" in install|uninstall) ;; *) fail "unknown action '$action' (use install or uninstall)";; esac
[ -n "$TEST" ] || [ "$(uname -s)" = Darwin ] || fail 'this installer is for macOS. On Windows run Install.cmd.'
[ -n "${HOME:-}" ] && [ "${HOME#/}" != "$HOME" ] || fail 'HOME is not set to an absolute path.'

dir="$(CDPATH='' cd -- "$(dirname -- "$0")" >/dev/null 2>&1 && pwd -P)" || fail 'cannot resolve the package folder.'
helper="$dir/CharacterBridge"
cli="$dir/character-api"

# A path goes into JSON: refuse control characters, escape backslash and double quote.
case "$dir$HOME" in *[[:cntrl:]]*|*'|'*) fail 'the package folder or home folder path contains control characters or "|"; move the package folder.';; esac
case "$dir" in
  /Volumes/*) fail 'the package is on a disk image or external drive. Copy the folder to your Mac (for example ~/Applications/DDB-Character-API) and run the installer there.';;
  "$HOME/Downloads"|"$HOME/Downloads/"*|"$HOME/Desktop"|"$HOME/Desktop/"*|"$HOME/Documents"|"$HOME/Documents/"*) [ "$action" = uninstall ] || say "Note: macOS asks Chrome/Brave for permission to use files in Downloads, Desktop and Documents. A folder such as ~/Applications/DDB-Character-API avoids that prompt.";;
esac
case "$dir" in */AppTranslocation/*) fail 'macOS is running this from a temporary copy (App Translocation). Move the folder out of Downloads into a permanent place first, then run the installer from there.';; esac
json_string() { printf '%s' "$1" | sed -e 's/\\/\\\\/g' -e 's/"/\\"/g'; }
manifest() {
  printf '{\n  "name": "%s",\n  "description": "%s",\n  "path": "%s",\n  "type": "stdio",\n  "allowed_origins": ["%s"]\n}\n' \
    "$HOST" "$DESCRIPTION" "$(json_string "$1")" "$ORIGIN"
}
# The helper path recorded in a manifest this installer generated; empty when the file is not ours.
owned_path() {
  local file="$1" line value
  [ "$(wc -l < "$file" | tr -d ' ')" = 7 ] || return 0
  line="$(sed -n 4p "$file")"
  case "$line" in '  "path": "'*'",') ;; *) return 0;; esac
  value="${line#  \"path\": \"}"; value="${value%\",}"
  value="$(printf '%s' "$value" | sed -e 's/\\"/"/g' -e 's/\\\\/\\/g')"
  [ "$(manifest "$value")" = "$(cat "$file")" ] && printf '%s' "$value"
  return 0
}

support="$HOME/Library/Application Support"
have_chrome=''; have_brave=''
[ -d "$support/Google/Chrome" ] && have_chrome=1
[ -d "$support/BraveSoftware/Brave-Browser" ] && have_brave=1
# Chrome reads Google/Chrome/NativeMessagingHosts. Brave is registered in that folder as well as its own, so it
# finds the helper whichever of the two its version reads. Each entry: label|browser folder in use?|registration folder
# One installer at a time per user: two copies installing at once could otherwise both pass the ownership checks.
lock="${TMPDIR:-/tmp}/com.tabletopvr.character_bridge.$(id -u).lock"
mkdir "$lock" 2>/dev/null || fail "another Character API installer is running. If none is, delete $lock and try again."
trap 'rmdir "$lock" 2>/dev/null' EXIT

browsers=("Google Chrome's folder|${have_chrome}${have_brave}|Google/Chrome" "Brave's folder|${have_brave}|BraveSoftware/Brave-Browser")

# ---- preflight: decide every change before writing anything
plan=()        # entries: name|target|write|remove|skip
for entry in "${browsers[@]}"; do
  name="${entry%%|*}"; rest="${entry#*|}"; used="${rest%%|*}"; base="$support/${rest#*|}"
  target="$base/NativeMessagingHosts/$HOST.json"
  if [ -z "$used" ] && [ ! -e "$target" ]; then plan+=("$name|$target|skip"); continue; fi
  if [ -L "$target" ] || { [ -e "$target" ] && [ ! -f "$target" ]; }; then fail "$target is not a regular file; remove it yourself if it is not needed."; fi
  if [ -L "$base" ] || [ -L "$base/NativeMessagingHosts" ]; then fail "$base or its NativeMessagingHosts folder is a symbolic link."; fi
  old=''
  if [ -f "$target" ]; then
    old="$(owned_path "$target")"
    if [ -z "$old" ]; then
      if [ "$action" = uninstall ]; then plan+=("$name|$target|foreign"); continue; fi
      fail "$name already has a different $HOST registration ($target) that this installer did not create."
    fi
  fi
  if [ "$action" = uninstall ]; then
    if [ -n "$old" ] && [ "$old" = "$helper" ]; then plan+=("$name|$target|remove")
    elif [ -n "$old" ]; then plan+=("$name|$target|other:$old")
    else plan+=("$name|$target|none"); fi
    continue
  fi
  if [ -n "$old" ] && [ "$old" != "$helper" ] && [ -d "$(dirname "$old")" ]; then
    fail "$name is registered to another copy that still exists: $(dirname "$old"). Run Uninstall.command in that folder first, or delete that folder."
  fi
  plan+=("$name|$target|write")
done

if [ "$action" = install ]; then
  [ -n "$have_chrome$have_brave" ] || fail 'neither Google Chrome nor Brave has been opened on this Mac user account yet. Open one of them once, then run the installer again.'
  [ -f "$helper" ] && [ ! -L "$helper" ] || fail "CharacterBridge is missing next to this installer ($dir)."
  [ -f "$cli" ] && [ ! -L "$cli" ] || fail "character-api is missing next to this installer ($dir)."
  # The package's architecture must run here (an Intel build runs on Apple silicon only through Rosetta 2).
  magic="$(od -An -tx1 -N8 "$helper" | tr -d ' \n')"
  # hw.optional.arm64 is 1 on Apple silicon even inside a Rosetta (x86_64) Terminal, where uname -m says x86_64.
  apple_silicon="$(sysctl -n hw.optional.arm64 2>/dev/null || echo 0)"
  case "$magic" in
    cffaedfe0c000001) [ "$apple_silicon" = 1 ] || [ -n "$TEST" ] || fail 'this package is for Apple silicon Macs; download the macOS Intel package instead.';;
    cffaedfe07000001) [ "$apple_silicon" != 1 ] || [ -n "$TEST" ] || say 'Note: this is the Intel package; on Apple silicon it runs through Rosetta 2. The Apple silicon package is faster.';;
    7f454c46*) [ -n "$TEST" ] || fail 'CharacterBridge is not a macOS program.';;
    *) fail 'CharacterBridge is not a recognised macOS program.';;
  esac
  chmod 755 "$helper" "$cli" || fail 'could not mark the helper programs as executable.'
  if [ -z "$TEST" ]; then
    # The release is not notarized by Apple. Running this installer is the user's decision to trust it: remove the
    # download quarantine from the two helper programs only, and make sure each carries a valid (ad hoc) signature,
    # which Apple silicon requires for every program.
    for program in "$helper" "$cli"; do
      xattr -d com.apple.quarantine "$program" 2>/dev/null || true
      if ! codesign --verify "$program" 2>/dev/null; then
        codesign --force --sign - "$program" 2>/dev/null || fail "$(basename "$program") has no valid signature and could not be signed ad hoc here (macOS may ask to install the command line developer tools for that)."
      fi
    done
  fi
  # Proof it can start here: an unknown argument makes the helper exit 64 before it touches anything.
  "$helper" --installer-check </dev/null >/dev/null 2>&1; code=$?
  [ "$code" = 64 ] || fail "CharacterBridge could not run on this Mac (exit $code). On Apple silicon with the Intel package, install Rosetta 2 (softwareupdate --install-rosetta)."
fi

# ---- apply, rolling back on any failure
done_list=()
rollback() {
  local item target backup
  [ "${#done_list[@]}" -gt 0 ] || return 0   # bash 3.2 + set -u: never expand an empty array
  for item in "${done_list[@]}"; do
    target="${item%%|*}"; backup="${item#*|}"
    if [ "$backup" = '-' ]; then rm -f "$target"; else mv -f "$backup" "$target"; fi
  done
}
cleanup() {
  local item backup
  [ "${#done_list[@]}" -gt 0 ] || return 0
  for item in "${done_list[@]}"; do backup="${item#*|}"; [ "$backup" = '-' ] || rm -f "$backup"; done
}
# Interrupted (Ctrl-C, Terminal closed) while applying: restore what was already changed.
trap 'rollback; cleanup; rmdir "$lock" 2>/dev/null; printf "Interrupted. Previous registrations were restored.\n" >&2; exit 130' INT TERM HUP
for item in "${plan[@]}"; do
  name="${item%%|*}"; rest="${item#*|}"; target="${rest%%|*}"; what="${rest#*|}"
  case "$what" in
    write|remove)
      backup='-'
      if [ -f "$target" ]; then
        backup="$target.previous.$$"
        cp -p "$target" "$backup" || { rollback; fail "could not back up $target."; }
      fi
      done_list+=("$target|$backup")
      if [ "$what" = write ]; then
        mkdir -p "$(dirname "$target")" && manifest "$helper" > "$target.tmp.$$" && mv -f "$target.tmp.$$" "$target" \
          || { rm -f "$target.tmp.$$"; rollback; printf 'Installation stopped: could not write %s.\nPrevious registrations were restored.\n' "$target" >&2; exit 1; }
      else
        rm -f "$target" || { rollback; printf 'Uninstall stopped: could not remove %s.\nPrevious registrations were restored.\n' "$target" >&2; exit 1; }
      fi;;
  esac
done
cleanup
done_list=()
trap - INT TERM HUP

for item in "${plan[@]}"; do
  name="${item%%|*}"; rest="${item#*|}"; what="${rest#*|}"
  case "$what" in
    write) say "Registered for $name.";;
    remove) say "Removed the registration for $name.";;
    skip) say "$name is not set up on this Mac user account (skipped).";;
    none) say "$name had no registration.";;
    foreign) say "$name has a registration this installer did not create; left unchanged.";;
    other:*) say "$name is registered to another copy (${what#other:}); left unchanged.";;
  esac
done
if [ "$action" = install ]; then
  say "Character API helper installed from: $dir"
  say 'Keep this folder where it is (moving or deleting it breaks the connection; run Install.command again after a move).'
  say 'Reload the extension in chrome://extensions or brave://extensions, then check its Connection help page.'
  say "Local apps find the API in: $support/TabletopVR/character-bridge/v2/http.json"
else
  say 'Remove the unpacked extension in Chrome or Brave if you no longer need it. Your API settings were kept.'
fi
